INSERT INTO public.sop_templates (id, shift_code, time_range, title, description, category, priority, order_num) VALUES
  ('task_p1_1', 'P1', '06:45', 'Presensi & Apel Pagi Sesi 1', 'Hadir 15 menit sebelum shif (06:45), presensi kedatangan dan apel koordinasi piket pagi sesi 1.', 'presensi', 'krusial', 1),
  ('task_p1_2', 'P1', '07:15', 'Monitoring Sarapan & Kesiapan Sekolah', 'Mendampingi anak asuh di ruang makan, cek seragam, kerapihan, dan kelengkapan alat belajar.', 'makan', 'penting', 2),
  ('task_p1_3', 'P1', '08:30', 'Pemeriksaan Kerapihan & Sanitasi Kamar Asrama', 'Inspeksi kebersihan barak/kamar tidur, ventilasi, dan kerapihan tempat tidur anak asuh.', 'kebersihan', 'normal', 3),
  ('task_p1_4', 'P1', '12:00', 'Sholat Dzuhur Berjamaah & Makan Siang Siswa', 'Pendampingan sholat Dzuhur di musholla asrama dilanjutkan makan siang tertib bersama.', 'ibadah', 'penting', 4),
  ('task_p1_5', 'P1', '14:00', 'Pengecekan Kesehatan & Pendampingan Siswa Sakit', 'Memantau kondisi fisik anak asuh di UKS, koordinasi pemberian obat atau rujukan jika diperlukan.', 'patroli', 'penting', 5),
  ('task_p1_6', 'P1', '14:45', 'Pengisian Buku Jaga & Serah Terima ke Shif Sore', 'Mencatat mutasi kejadian, log harian, dan briefing serah terima buku jurnal kepada tim shif sore (15:00).', 'laporan', 'krusial', 6),
  ('task_p2_1', 'P2', '07:45', 'Presensi & Koordinasi Piket Pagi Sesi 2', 'Hadir pukul 07:45, presensi dinas dan koordinasi tugas harian dengan tim sesi 1.', 'presensi', 'krusial', 7),
  ('task_p2_2', 'P2', '08:30', 'Monitoring Operasional Asrama & Sanitasi Barak', 'Pengecekan kebersihan lingkungan asrama, sanitasi toilet, dan ketersediaan air bersih.', 'kebersihan', 'normal', 8),
  ('task_p2_3', 'P2', '10:00', 'Patroli Lingkungan & Pendampingan Santri di UKS', 'Patroli area sekolah/asrama serta pendampingan perawatan anak asuh yang sedang istirahat di UKS.', 'patroli', 'penting', 9),
  ('task_p2_4', 'P2', '12:00', 'Sholat Dzuhur Berjamaah & Pendampingan Makan Siang', 'Membantu ketertiban sholat Dzuhur berjamaah dan pengawasan antrean makan siang siswa.', 'ibadah', 'penting', 10),
  ('task_p2_5', 'P2', '14:00', 'Monitoring Kepulangan Sekolah & Penjemputan Anak', 'Memantau kembalinya siswa dari sekolah ke asrama, ketertiban ganti pakaian dan barang bawaan.', 'belajar', 'penting', 11),
  ('task_p2_6', 'P2', '15:45', 'Pengisian Log Harian P2 & Koordinasi Akhir Tugas', 'Input laporan piket P2, sinkronisasi catatan dinas dengan tim piket sore hingga pukul 16:00 WIB.', 'laporan', 'krusial', 12),
  ('task_p3_1', 'P3', '06:45', 'Presensi & Apel Koordinasi Upacara Senin', 'Hadir 15 menit sebelum shif (06:45), presensi kedatangan dan apel koordinasi pengamanan upacara bendera.', 'presensi', 'krusial', 13),
  ('task_p3_2', 'P3', '07:00', 'Pengawalan Barisan & Kerapihan Seragam Upacara', 'Pengecekan kelengkapan atribut seragam santri (topi, dasi, ikat pinggang, kaos kaki, sepatu) sebelum menuju lapangan.', 'patroli', 'krusial', 14),
  ('task_p3_3', 'P3', '07:30', 'Pendampingan Upacara Bendera & Penanganan Santri Sakit', 'Memantau ketertiban barisan santri selama upacara berlangsung, evakuasi dan perawatan santri yang pingsan/lemas di pos UKS.', 'patroli', 'krusial', 15),
  ('task_p3_4', 'P3', '09:30', 'Pemeriksaan Kebersihan & Kerapihan Barak Asrama', 'Inspeksi kebersihan barak, ventilasi udara, dan kerapihan kasur/loker setelah santri memasuki ruang kelas belajar.', 'kebersihan', 'normal', 16),
  ('task_p3_5', 'P3', '12:00', 'Sholat Dzuhur Berjamaah & Pendampingan Makan Siang', 'Pendampingan sholat Dzuhur berjamaah santri dilanjutkan pengawasan antrean makan siang tertib bersama.', 'ibadah', 'penting', 17),
  ('task_p3_6', 'P3', '14:00', 'Monitoring KBM & Kepulangan Santri dari Sekolah', 'Memantau kepulangan santri dari ruang kelas ke asrama, ketertiban ganti pakaian, dan barang inventaris santri.', 'belajar', 'penting', 18),
  ('task_p3_7', 'P3', '15:45', 'Pengisian Jurnal Dinas P3 & Serah Terima ke Shif Sore', 'Mencatat evaluasi kedisiplinan upacara, mutasi anak asuh sakit/izin, dan briefing serah terima dinas kepada tim piket sore hingga pukul 16:00 WIB.', 'laporan', 'krusial', 19),
  ('task_p_1', 'P', '06:45', 'Presensi & Apel Pagi Wali Asuh', 'Hadir 15 menit sebelum shif, lakukan presensi kedatangan dan apel koordinasi piket pagi.', 'presensi', 'krusial', 20),
  ('task_p_2', 'P', '07:15', 'Monitoring Sarapan & Kesiapan Sekolah', 'Mendampingi anak asuh di ruang makan, cek seragam, kerapihan, dan kelengkapan alat belajar.', 'makan', 'penting', 21),
  ('task_p_3', 'P', '08:30', 'Pemeriksaan Kerapihan & Sanitasi Kamar Asrama', 'Inspeksi kebersihan barak/kamar tidur, ventilasi, dan kerapihan tempat tidur anak asuh.', 'kebersihan', 'normal', 22),
  ('task_p_4', 'P', '12:00', 'Sholat Dzuhur Berjamaah & Makan Siang Siswa', 'Pendampingan sholat Dzuhur di musholla asrama dilanjutkan makan siang tertib bersama.', 'ibadah', 'penting', 23),
  ('task_p_5', 'P', '14:00', 'Pengecekan Kesehatan & Pendampingan Siswa Sakit', 'Memantau kondisi fisik anak asuh di UKS, koordinasi pemberian obat atau rujukan jika diperlukan.', 'patroli', 'penting', 24),
  ('task_p_6', 'P', '14:45', 'Pengisian Buku Jaga & Serah Terima ke Shif Sore', 'Mencatat mutasi kejadian, log harian, dan briefing serah terima buku jurnal kepada tim shif sore (15:00).', 'laporan', 'krusial', 25),
  ('task_s_1', 'S', '15:00', 'Serah Terima Shif (Handover) & Cek Absensi Sore', 'Menerima buku jaga dari piket pagi, cek jumlah anak asuh lengkap di asrama.', 'presensi', 'krusial', 26),
  ('task_s_2', 'S', '16:00', 'Pendampingan Olahraga / Ekstrakurikuler Mandiri', 'Mengarahkan dan mengawasi kegiatan fisik/olahraga sore anak asuh di lapangan.', 'belajar', 'normal', 27),
  ('task_s_3', 'S', '17:30', 'Persiapan Mandi Bersih & Sholat Maghrib Berjamaah', 'Memastikan semua anak asuh sudah mandi rapi, wudhu, dan berkumpul di musholla.', 'ibadah', 'krusial', 28),
  ('task_s_4', 'S', '18:30', 'Makan Malam Bersama & Kultum/Mengaji', 'Pendampingan makan malam santun dan kegiatan mengaji Al-Quran / bimbingan rohani singkat.', 'makan', 'penting', 29),
  ('task_s_5', 'S', '19:30', 'Sholat Isya Berjamaah & Jam Belajar Mandiri (Belajar Malam)', 'Pelaksanaan sholat Isya dilanjutkan belajar terbimbing, penyelesaian PR dan tugas sekolah.', 'belajar', 'penting', 30),
  ('task_s_6', 'S', '22:30', 'Pengecekan Kamar Tidur & Persiapan Istirahat Malam', 'Absensi malam di tiap kamar, cek pintu & jendela kamar, pemadaman lampu utama barak.', 'patroli', 'krusial', 31),
  ('task_s2a_1', 'S2A', '15:00', 'Serah Terima Shif & Koordinasi Menu Kantin SMP', 'Serah terima buku jaga dan koordinasi dengan pengelola dapur/kantin terkait kesiapan makan sore/malam anak asuh SMP.', 'makan', 'krusial', 32),
  ('task_s2a_2', 'S2A', '16:30', 'Pengecekan Kebersihan & Kesiapan Meja Makan SMP', 'Mensterilkan dan menyiapkan peralatan makan, air minum, dan area prasmanan kantin SMP.', 'kebersihan', 'normal', 33),
  ('task_s2a_3', 'S2A', '18:15', 'Pendampingan Makan Malam & Prasmanan Siswa SMP', 'Mengatur antrean tertib makan anak asuh SMP, adab makan, porsi gizi berimbang, dan doa bersama.', 'makan', 'krusial', 34),
  ('task_s2a_4', 'S2A', '19:15', 'Operasional Pembersihan & Inventarisasi Alat Makan SMP', 'Memastikan cuci piring/peralatan makan selesai higienis dan kantin SMP dalam kondisi terkunci rapi.', 'kebersihan', 'penting', 35),
  ('task_s2a_5', 'S2A', '20:00', 'Monitoring Snack Malam & Pendampingan Belajar SMP', 'Mendukung tim piket asrama dalam membagikan kudapan malam serta monitoring belajar mandiri SMP.', 'belajar', 'normal', 36),
  ('task_s2a_6', 'S2A', '21:30', 'Pengecekan Kamar Tidur & Barak SMP', 'Membantu absensi malam dan patroli kamar tidur anak asuh SMP sebelum jam istirahat malam.', 'patroli', 'krusial', 37),
  ('task_s3a_1', 'S3A', '15:00', 'Serah Terima Shif & Koordinasi Menu Kantin SMA', 'Serah terima buku jaga dan koordinasi dengan petugas katering/kantin terkait kesiapan logistik makan malam anak asuh SMA.', 'makan', 'krusial', 38),
  ('task_s3a_2', 'S3A', '16:30', 'Pengecekan Kebersihan & Kesiapan Meja Makan SMA', 'Memastikan sanitasi ruang makan SMA, kelengkapan alat makan, dan dispenser air minum terisi penuh.', 'kebersihan', 'normal', 39),
  ('task_s3a_3', 'S3A', '18:15', 'Pendampingan Makan Malam & Prasmanan Siswa SMA', 'Mengawasi alur antrean prasmanan anak asuh SMA, memastikan kecukupan porsi, ketertiban, dan doa bersama.', 'makan', 'krusial', 40),
  ('task_s3a_4', 'S3A', '19:15', 'Pembersihan Ruang Makan & Sanitasi Kantin SMA', 'Inspeksi kebersihan meja makan, pembuangan sisa makanan, dan penguncian fasilitas kantin SMA.', 'kebersihan', 'penting', 41),
  ('task_s3a_5', 'S3A', '20:00', 'Pendampingan Belajar Terbimbing & Tugas SMA', 'Mendampingi anak asuh SMA dalam jam belajar mandiri dan pengerjaan tugas proyek sekolah.', 'belajar', 'normal', 42),
  ('task_s3a_6', 'S3A', '22:30', 'Pengecekan Kamar & Presensi Malam Barak SMA', 'Pengecekan akhir kamar tidur anak asuh SMA, ventilasi, dan kepatuhan jam istirahat malam.', 'patroli', 'krusial', 43),
  ('task_s4a_1', 'S4A', '15:00', 'Serah Terima Shif & Monitoring Area Masjid', 'Serah terima buku jaga dan koordinasi pengawasan area masjid, lingkungan luar kantin dan asrama.', 'presensi', 'krusial', 44),
  ('task_s4a_2', 'S4A', '16:30', 'Pengecekan Kebersihan & Kesiapan Tempat Wudhu Masjid', 'Pengecekan fasilitas wudhu, ketersediaan air bersih, sajadah, dan sound system masjid.', 'kebersihan', 'normal', 45),
  ('task_s4a_3', 'S4A', '17:30', 'Pengarahan & Pendampingan Sholat Maghrib Berjamaah', 'Mengarahkan seluruh anak asuh wudhu tertib, mobilisasi ke masjid, dan sholat Maghrib berjamaah.', 'ibadah', 'krusial', 46),
  ('task_s4a_4', 'S4A', '18:30', 'Monitoring Arus Santri & Patroli Luar Asrama', 'Memantau pergerakan anak asuh keluar masjid menuju ruang makan, patroli area luar kantin & selasar asrama.', 'patroli', 'penting', 47),
  ('task_s4a_5', 'S4A', '19:15', 'Pendampingan Sholat Isya & Bimbingan Rohani Masjid', 'Pendampingan sholat Isya berjamaah, doa bersama, dan pengawasan santun anak asuh di masjid.', 'ibadah', 'krusial', 48),
  ('task_s4a_6', 'S4A', '22:30', 'Penguncian Pintu Masjid & Patroli Keamanan Luar', 'Memadamkan lampu operasional masjid, mengunci pintu jendela masjid, dan patroli penertiban malam.', 'patroli', 'krusial', 49),
  ('task_m1_1', 'M1', '23:00', 'Penguncian Pintu Gedung & Patroli Keamanan Asrama 1', 'Kunci gerbang & pintu utama asrama, periksa instalasi listrik, air, dan keamanan perimeter (Sesi 1).', 'patroli', 'krusial', 50),
  ('task_m1_2', 'M1', '00:00', 'Patroli Jam Istirahat & Cek Keberadaan Siswa Sesi 1', 'Keliling lorong dan kamar asrama memastikan seluruh siswa tidur tertib dan situasi kondusif.', 'patroli', 'penting', 51),
  ('task_m1_3', 'M1', '04:15', 'Membangunkan Siswa untuk Sholat Subuh Berjamaah Sesi 1', 'Membangunkan seluruh anak asuh, mendampingi wudhu dan pelaksanaan sholat Subuh berjamaah.', 'ibadah', 'krusial', 52),
  ('task_m2_1', 'M2', '23:30', 'Patroli Keamanan & Lingkungan Asrama Sesi 2', 'Pemeriksaan keamanan area asrama, pantau perimeter dan cek gerbang gedung.', 'patroli', 'krusial', 53),
  ('task_m2_2', 'M2', '03:00', 'Patroli Dini Hari & Pengecekan Lingkungan Sesi 2', 'Patroli putaran dini hari, pantau CCTV dan area sekitar gedung asrama.', 'patroli', 'penting', 54),
  ('task_m2_3', 'M2', '05:30', 'Senam Pagi / Kerja Bakti Lingkungan Asrama Sesi 2', 'Mengarahkan anak asuh olahraga pagi ringan dan membersihkan area lingkungan asrama.', 'kebersihan', 'normal', 55),
  ('task_m_1', 'M', '23:00', 'Penguncian Pintu Gedung & Patroli Keamanan Asrama 1', 'Kunci gerbang & pintu utama asrama, periksa instalasi listrik, air, dan keamanan perimeter.', 'patroli', 'krusial', 56),
  ('task_m_2', 'M', '00:00', 'Patroli Jam Istirahat & Cek Keberadaan Siswa', 'Keliling lorong dan kamar asrama memastikan seluruh siswa tidur tertib dan situasi kondusif.', 'patroli', 'penting', 57),
  ('task_m_3', 'M', '03:00', 'Patroli Dini Hari & Pengecekan Lingkungan', 'Patroli putaran dini hari, pantau CCTV dan area sekitar gedung asrama.', 'patroli', 'penting', 58),
  ('task_m_4', 'M', '04:15', 'Membangunkan Siswa untuk Sholat Subuh Berjamaah', 'Membangunkan seluruh anak asuh, mendampingi wudhu dan pelaksanaan sholat Subuh berjamaah.', 'ibadah', 'krusial', 59),
  ('task_m_5', 'M', '05:30', 'Senam Pagi / Kerja Bakti Lingkungan Asrama', 'Mengarahkan anak asuh olahraga pagi ringan dan membersihkan area lingkungan asrama.', 'kebersihan', 'normal', 60),
  ('task_m_6', 'M', '07:00', 'Piket Pagi Lanjutan & Serah Terima Piket ke Shif Pagi Baru', 'Memastikan sarapan berjalan lancar, input log malam, dan serah terima piket (LP).', 'laporan', 'krusial', 61)
